import {performance} from 'node:perf_hooks'

/**
 * Runs a durable function handler
 * @param handler - callback being run
 * @param context - data to send to the operation
 * @param event - the step being run
 * @param logger
 * @param io
 */
export async function runDurable(handler, {context, event, logger}, io) {
  const track = async (name, kind, produce) => {
    io.emit({name, kind, phase: 'start'})
    const startedAt = performance.now()
    try {
      const value = await produce()
      io.emit({
        name,
        kind,
        phase: 'complete',
        output: value,
        durationMs: performance.now() - startedAt,
      })
      return value
    } catch (err) {
      io.emit({
        name,
        kind,
        phase: 'error',
        error: {
          name: err?.name ?? 'Error',
          message: err?.message ?? String(err),
          stack: err?.stack ?? '',
        },
        durationMs: performance.now() - startedAt,
      })
      throw err
    }
  }

  const step = {
    run: ({name, handler: fn}) => track(name || 'step-run', 'run', () => fn({logger, attempt: 1})),
  }

  return handler({context, event, step, logger})
}
